		if rec := recover(); rec != nil {
			ctx := observability.ExtractNATSHeader(context.Background(), msg.Header)
			observability.Ctx(ctx, r.logger).Error("snapshot.v2 panic", zap.Any("panic", rec))
		}
	}()

	var p snapshotV2Payload
	if err := json.Unmarshal(msg.Data, &p); err != nil {
		ctx := observability.ExtractNATSHeader(context.Background(), msg.Header)
		observability.Ctx(ctx, r.logger).Error("snapshot.v2 invalid payload",
			zap.Error(err), zap.ByteString("data", msg.Data))
		return
	}
	if p.SourceObjectID <= 0 {
		ctx := observability.ExtractNATSHeader(context.Background(), msg.Header)
		observability.Ctx(ctx, r.logger).Error("snapshot.v2 source_object_id missing", zap.ByteString("data", msg.Data))
		return
	}
	if p.TraceID == "" {
		p.TraceID = strings.TrimSpace(msg.Header.Get("Cdc-Correlation-Id"))
	}
	if p.TraceID == "" {
		p.TraceID = fmt.Sprintf("worker-snapshot.v2-%d", time.Now().UnixNano())
	}
	if p.BatchSize > snapshotV2MaxBatchSize {
		p.BatchSize = snapshotV2MaxBatchSize
	}

	jobID := msg.Header.Get("Cdc-Job-Id")

	go func(p snapshotV2Payload, jobID string, header nats.Header) {
		ctx := observability.ExtractNATSHeader(context.Background(), map[string][]string(header))
		ctx, span := observability.ChildSpan(ctx, "nats.SnapshotV2Runner")
		defer span.End()

		if sc := span.SpanContext(); sc.IsValid() {
			p.TraceID = sc.TraceID().String()
		}

		if err := r.runSnapshot(ctx, p, jobID); err != nil {
			observability.Ctx(ctx, r.logger).Error("snapshot.v2 run failed",
				zap.Int64("source_object_id", p.SourceObjectID),
				zap.String("trace_id", p.TraceID),
				zap.String("job_id", jobID),
				zap.Error(err))
		}
	}(p, jobID, msg.Header)

